using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace LittleLeo.Variables;

[CreateAssetMenu(menuName = "Variables References/Int Reference")]
public class IntReference : GameEvent<int>
{
	[Header("Variable")]
	[SerializeField]
	[HideIf("allowBothSets")]
	private bool externalSet;

	[SerializeField]
	private bool allowBothSets;

	[SerializeField]
	private int value;

	public int Value => value;

	public void SetValue(int value)
	{
		if (externalSet || allowBothSets)
		{
			this.value = value;
			Raise(value);
		}
		else
		{
			Debug.Log($"Cannot set {base.name} from external source, because bool externalSet is false");
		}
	}

	public void ChangeAmount(int amount)
	{
		if (externalSet)
		{
			value += amount;
			Raise(value);
		}
		else
		{
			Debug.Log($"Cannot set {base.name} from external source, because bool externalSet is false");
		}
	}
}
